		private static int[] order = new int[]
		{
			5, 22, 23, 46, 21, 32, 20, 50, 40, 26,
			55, 51, 35, 59, 36, 45, 54, 49, 57, 42,
			20, 34, 36, 45, 30, 52, 51, 42, 59, 52,
			46, 31, 43, 59, 56, 45, 45, 46, 55, 44,
			50, 53, 46, 48, 55, 51, 53, 48, 59, 52,
			52, 54, 56, 59, 56, 58, 59, 59, 59, 59,
			60
		};

		private static int key = 99;

		public static readonly bool IsPopulated = true;

		public static byte[] Data()
